select * from ( SELECT DISTINCT(documento.cd_paciente)      		    AS cdPaciente            ,       paciente.nm_paciente  AS nmPaciente                                       ,        UPPER (CASE WHEN Length( nvl( pagu_objeto.NM_OBJETO , '' ) ) > 0 THEN '['|| pagu_objeto.NM_OBJETO||'] - ' || tipo.ds_tipo_documento ELSE tipo.ds_tipo_documento  END ) AS descricao ,        UPPER (CASE WHEN Length(nvl( pagu_objeto.NM_OBJETO , '' ) ) > 0 THEN pagu_objeto.NM_OBJETO ELSE '' END ) AS objeto ,        tipo.ds_tipo_documento AS tipoDocumento   ,        documento.dh_criacao					        AS data  ,        documento.cd_prestador                       AS cdPrestador           ,        documento.cd_documento_clinico 		        AS cdDocumentoClinico 	 ,        DECODE(favorito.cd_paciente, NULL, 'N', 'S') AS isFavorito FROM usuario_banco.pw_documento_clinico documento      INNER JOIN usuario_banco.pw_tipo_documento tipo           ON (tipo.cd_tipo_documento = documento.cd_tipo_documento)      LEFT OUTER JOIN usuario_banco.pw_favorito_paciente favorito           ON (documento.cd_paciente                  = favorito.cd_paciente)      LEFT OUTER JOIN usuario_banco.pagu_objeto           ON (pagu_objeto.cd_objeto                  = documento.cd_objeto)      LEFT JOIN usuario_banco.paciente paciente on ( paciente.cd_paciente = documento.cd_paciente )      inner join ATENDIME a on ( a.cd_atendimento = documento.cd_atendimento )  WHERE documento.tp_status = 'FECHADO' 	 AND ( pagu_objeto.sn_assinatura <> 'N' or documento.cd_objeto is null ) 	 AND tipo.sn_pendencias_alertas = 'S' 	 AND (documento.dh_criacao >= tipo.dh_pendencias_alertas 	      OR tipo.dh_pendencias_alertas IS NULL)  	 AND documento.cd_paciente IS NOT NULL  	 AND documento.cd_atendimento IS NOT NULL      AND             ( documento.cd_prestador =:1                OR             documento.cd_usuario_autorizador =:2            )  and a.CD_MULTI_EMPRESA = 1    AND           (              tipo.tp_documento <> 'AVAFAR' or             (  tipo.tp_documento = 'AVAFAR' and                 exists ( select 1 from usuario_banco.PW_AVALIACAO_PRE_MED where CD_DOCUMENTO_CLINICO = documento.CD_DOCUMENTO_CLINICO )              )          )    	ORDER BY documento.dh_criacao desc, nmPaciente ) where rownum <= :3 